record.field:
if records:
    receipts = records.filtered(
        lambda picking: picking.picking_type_code == "incoming"
        and picking.state in ("done", "cancel")
    )
    if receipts:
        orders = receipts.mapped("move_ids.purchase_line_id.order_id")
        for order in orders:
            open_lines = order.order_line.filtered(
                lambda line: line.product_id
                and not line.display_type
                and line.product_uom_id.compare(line.qty_received, line.product_qty) < 0
                and line.date_planned
                and any(
                    move.picking_id and move.picking_id.state not in ("done", "cancel")
                    for move in line.move_ids
                )
            )
            dates = open_lines.mapped("date_planned")
            if dates:
                expected_arrival = min(dates)
                if order.date_planned != expected_arrival:
                    order.write({"date_planned": expected_arrival})

if records:
    lines = records.filtered(lambda l: l.product_id and not l.display_type and l.date_planned)
    for line in lines:
        open_moves = line.move_ids.filtered(lambda m: m.state not in ("done", "cancel"))
        if open_moves:
            to_update = open_moves.filtered(lambda m: m.date != line.date_planned)
            if to_update:
                to_update.write({"date": line.date_planned})
